      "text": "Returns 0xFFFFFFFFFFFFFFFF when the input length is less than 3.",
      "asserted_values": ["0xFFFFFFFFFFFFFFFF"],
      "confidence": 0.9,
      "io": {
        "when": "len < 3",
        "returns": "0xFFFFFFFFFFFFFFFF"
      }
    },
    {
      "id": "3",
      "type": "IO",
      "text": "Returns the length of the output when the input length is a multiple of 3.",
      "asserted_values": [],
      "confidence": 0.9,
      "io": {
        "when": "len % 3 == 0",
        "returns": "len"
      }
    },
    {
      "id": "4",
      "type": "IO",
      "text": "Returns the length of the output plus 4 when the input length is 1 or 2.",
      "asserted_values": [],
      "confidence": 0.9,
      "io": {
        "when": "len == 1 || len == 2",
        "returns": "len + 4"
      }
    },
    {
      "id": "5",
      "type": "SIDE",
      "text": "Writes the encoded data to the output buffer.",
      "asserted_values": [],
      "confidence": 0.9
    },
    {
      "id": "6",
      "type": "CF",
      "text": "Uses a loop to process the input in chunks of 3 bytes.",
      "asserted_values": [],
      "confidence": 0.9
    },
    {
      "id": "7",
      "type": "CF",
      "text": "Handles the case when the input length is 1 or 2 outside the loop.",
      "asserted_values": [],
      "confidence": 0.9
    }
  ],
  "recovered_c": "uint64_t fn_07(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len < 3) {\n    return VERA_ERR;\n  }\n\n  size_t i = 0;\n  size_t j = 0;\n\n  while (i + 3 <= len) {\n    uint32_t chunk = ((uint32_t)in[i] << 16) | ((uint32_t)in[i + 1] << 8) | in[i + 2];\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(chunk >> 18) & 0x3F];\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(chunk >> 12) & 0x3F];\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(chunk >> 6) & 0x3F];\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[chunk & 0x3F];\n    i += 3;\n  }\n\n  if (len % 3 == 1) {\n    uint32_t chunk = (uint32_t)in[i] << 16;\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(chunk >> 18) & 0x3F];\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(chunk >> 12) & 0x3F];\n    out[j++] = '=';\n    out[j++] = '=';\n  } else if (len % 3 == 2) {\n    uint32_t chunk = ((uint32_t)in[i] << 16) | ((uint32_t)in[i + 1] << 8);\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(chunk >> 18) & 0x3F];\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(chunk >> 12) & 0x3F];\n    out[j++] = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"[(chunk >> 6) & 0x3F];\n    out[j++] = '=';\n  }\n\n  return j;\n}"
}
